import pandas as pd
import numpy as np

def clean_transactions(df: pd.DataFrame) -> pd.DataFrame:
    # Edge case: empty dataframe
    if df.empty:
        return df

    # 1. Deduplicate by transaction_id, keeping the first occurrence.
    # Edge case: all rows are duplicates -> result has 1 row per unique ID.
    df = df.drop_duplicates(subset='transaction_id', keep='first').copy()

    # 2. Parse mixed-format timestamps.
    # Try ISO 8601 first, then epoch seconds. Coerce failures to NaT.
    def parse_ts(val):
        if pd.isna(val):
            return pd.NaT
        val_str = str(val).strip()
        # Edge case: pure numeric string likely epoch seconds
        try:
            epoch = float(val_str)
            return pd.to_datetime(epoch, unit='s', utc=True)
        except (ValueError, OverflowError):
            pass
        # Try ISO 8601
        parsed = pd.to_datetime(val_str, errors='coerce', utc=True)
        return parsed

    df['timestamp'] = df['timestamp'].apply(parse_ts)

    # 3. Drop rows where user_id is NaN.
    # Edge case: all user_ids are NaN -> empty result.
    df = df.dropna(subset=['user_id']).copy()

    # 4. Parse amount strings with currency symbols and locale separators.
    def parse_amount(raw, currency_code):
        if pd.isna(raw):
            return np.nan
        s = str(raw).strip()
        # Remove common currency symbols and whitespace
        for sym in ['$', '€', '£', '¥', 'USD', 'EUR', 'GBP']:
            s = s.replace(sym, '')
        s = s.strip()
        # Handle European format: 1.234,56 -> 1234.56
        if ',' in s and '.' in s:
            # If comma is after last dot, treat dot as thousands sep
            if s.rfind(',') > s.rfind('.'):
                s = s.replace('.', '').replace(',', '.')
            else:
                s = s.replace(',', '')
        elif ',' in s:
            # Ambiguous: if exactly 2 digits after comma, treat as decimal
            parts = s.split(',')
            if len(parts) == 2 and len(parts[1]) == 2:
                s = s.replace(',', '.')
            else:
                s = s.replace(',', '')
        try:
            return float(s)
        except ValueError:
            return np.nan

    df['amount'] = df.apply(
        lambda r: parse_amount(r['amount'], r.get('currency', '')), axis=1
    )

    # 5. Drop rows where timestamp or amount could not be parsed.
    df = df.dropna(subset=['timestamp', 'amount']).copy()

    # 6. Sort by timestamp for downstream time-series use.
    df = df.sort_values('timestamp').reset_index(drop=True)

    return df

# Edge case handled: mixed epoch/ISO timestamps, duplicate IDs,
# NaN user_ids, locale-aware currency parsing, and empty input.

Architectural Decision: Use a client-generated idempotency key combined with a server-side idempotency store backed by a transactional database.

Design:
1. The client generates a unique idempotency key (UUID) for each logical payment intent and includes it in the request header.
2. The server checks the idempotency store before processing. If the key exists and the request hash matches, return the stored response without reprocessing.
3. If the key exists but the request hash differs, reject with a 422 (same key, different payload).
4. If the key does not exist, insert a record with status 'processing', execute the payment, then update the record with the final response and status 'completed'.
5. Use a database transaction or distributed lock to prevent two concurrent requests with the same key from both executing.

Trade-offs:
- Client-generated keys shift uniqueness responsibility to the client. Benefit: the server does not need to generate and distribute keys. Risk: clients may reuse keys incorrectly.
- Storing full responses increases storage but enables exact replay. Alternative: store only a reference and recompute, but this risks non-deterministic responses.
- The idempotency store must be transactional. A cache-only store (e.g., Redis without persistence) risks losing idempotency records on restart.

