import hashlib
import json

def compute_request_hash(payload: dict) -> str:
    canonical = json.dumps(payload, sort_keys=True, separators=(',', ':'))
    return hashlib.sha256(canonical.encode()).hexdigest()

def process_payment(idempotency_key: str, payload: dict, store):
    req_hash = compute_request_hash(payload)

    # Atomic check-and-insert using database transaction
    with store.transaction():
        existing = store.get(idempotency_key)
        if existing:
            if existing['request_hash'] != req_hash:
                return {'status': 422, 'error': 'Key reused with different payload'}
            if existing['status'] == 'completed':
                return existing['response']  # Replay stored response
            if existing['status'] == 'processing':
                return {'status': 409, 'error': 'Request already in progress'}

        # Insert new record atomically
        store.insert({
            'idempotency_key': idempotency_key,
            'request_hash': req_hash,
            'status': 'processing',
            'response': None
        })

    # Execute payment outside the lock to minimize hold time
    try:
        result = execute_payment(payload)
        response = {'status': 200, 'transaction_id': result['txn_id']}
    except PaymentError as e:
        response = {'status': 400, 'error': str(e)}

    # Finalize: update the idempotency record with the response
    with store.transaction():
        store.update(idempotency_key, {
            'status': 'completed',
            'response': response
        })

    return response

This ensures exactly-once processing semantics for each idempotency key, handles concurrent duplicates via the 'processing' state, and detects payload mismatches via request hashing.
